// Parallel /admin <-> /staff routes for the tools GRANTABLE_AREAS
// (lib/staff-grants.ts) exposes to both portals. An ADMIN account previewing
// /staff still receives their real ADMIN-scoped notifications (new tickets,
// replies, etc.) and their href is baked in as /admin/... at write time —
// correct when viewed from the admin portal, but the staff subdomain can't
// reach /admin/* at all (see middleware.ts's portal isolation), so clicking
// one there 404'd. Confirmed live 2026-09-03. Rewriting the DISPLAY href by
// portal (not the stored Notification.href, which stays correct for the
// admin side) fixes it without touching every notification-creation call
// site — same fix applies to AdminIndicators' two hardcoded links below.
const ADMIN_TO_STAFF_HREF: Record<string, string> = {
  "/admin/support": "/staff/support",
  "/admin/chat": "/staff/chat",
  "/admin/reddit": "/staff/reddit",
  "/admin/inbox": "/staff/inbox",
  "/admin/clients-basic": "/staff/clients",
  "/admin/tasks": "/staff/tasks",
};

export function portalHref(href: string, isStaffPortal: boolean): string {
  if (!isStaffPortal) return href;
  for (const [adminPrefix, staffPrefix] of Object.entries(ADMIN_TO_STAFF_HREF)) {
    if (href === adminPrefix || href.startsWith(`${adminPrefix}/`)) {
      return staffPrefix + href.slice(adminPrefix.length);
    }
  }
  return href;
}

export type NavChild = { label: string; href: string; badge?: number };
export type NavItem = {
  label: string;
  href: string;
  /**
   * Leading icon (key into the `icons` map below). Both portals supply one for
   * every item; the link degrades to its initial if a key is ever missing.
   */
  icon?: string;
  badge?: number;
  /**
   * Secondary destinations that live *behind* this entry. The sidebar never
   * expands them — the admin portal surfaces them as in-page sub-tabs (see
   * components/admin/SubTabs.tsx). They exist here so the sidebar row stays
   * highlighted while you're on one of them, and so ⌘K can still jump straight
   * to any of them. Customer nav passes none and renders exactly as before.
   */
  children?: NavChild[];
  /** Static uppercase text pill shown in place of a numeric badge (e.g. "FREE"). */
  tag?: string;
};
export type NavSection = {
  /**
   * Stable key for the section, used to persist its collapsed/expanded state
   * (admin portal only — see `collapsedGroups` below). Sections without one
   * (the customer portal doesn't supply it) fall back to their index, so they
   * still render correctly but just never persist a collapse a user never
   * gets the option to make outside the admin ops portal.
   */
  key?: string;
  label?: string;
  items: NavItem[];
};

export type ShellNotification = {
  id: string;
  title: string;
  body?: string | null;
  href?: string | null;
  readAt: string | null;
  createdAt: string;
};

