export function Shell({
  nav,
  user,
  notifications,
  impersonation,
  tag,
  indicatorAccess,
  children,
}: {
  nav: NavSection[];
  user: { name: string; email: string; role: string; balanceCents: number };
  notifications: ShellNotification[];
  impersonation?: { adminName: string; targetEmail: string } | null;
  tag?: string;
  /** Which floating attention bubbles this account can actually use — see
   *  AdminIndicators' own doc comment. Both default true (the admin portal
   *  never passes this; ADMIN always has full access). app/staff/layout.tsx
   *  computes these from the EMPLOYEE's real StaffGrants. */
  indicatorAccess?: { support?: boolean; inbox?: boolean };
  children: React.ReactNode;
}) {
  const pathname = usePathname();
  // Which portal is this Shell rendering? The admin ops layout passes tag="ops",
  // the new employee portal (app/staff/layout.tsx) passes tag="staff", and the
  // customer dashboard passes none. This drives which floating widgets mount:
  // the customer portal keeps the Feedback bubble (and the live-chat bubble from
  // the root layout), while both staff-facing portals swap them for the
  // support + email attention indicators. (Role is NOT a reliable signal here —
  // an ADMIN visiting /dashboard is still on the customer portal, and an ADMIN
  // previewing /staff is still on the employee portal.)
  const isAdminPortal = tag === "ops";
  const isStaffPortal = tag === "staff";
  // Full-bleed routes (the mail + calendar apps) opt out of the centered/padded
  // main so they fill the entire content area under the header with no gap.
