"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";

type Result = { type: string; label: string; sub?: string; href: string };
type NavEntry = { label: string; href: string; section?: string };

const typeIcons: Record<string, string> = {
  server: "🖥",
  hosting: "🌍",
  website: "🧩",
  email: "✉️",
  domain: "🌐",
  ticket: "🎫",
  customer: "👤",
  page: "→",
};

// Group headers, in the order groups should appear. The flat result order (nav
// pages first, then the API's own ordering) already matches this, so keyboard
// nav walks the list top-to-bottom exactly as it reads.
const typeLabels: Record<string, string> = {
  page: "Pages",
  server: "Servers",
  hosting: "Hosting",
  website: "Websites",
  email: "Email",
  domain: "Domains",
  ticket: "Tickets",
  customer: "Customers",
};

export function CommandPalette({ nav }: { nav: NavEntry[] }) {
  const [open, setOpen] = useState(false);
  const [q, setQ] = useState("");
  const [results, setResults] = useState<Result[]>([]);
  const [active, setActive] = useState(0);
  const router = useRouter();
  const inputRef = useRef<HTMLInputElement>(null);
  const debounce = useRef<ReturnType<typeof setTimeout> | null>(null);
  // Where focus was when the palette opened, so closing it (Escape, click-away,
  // navigation) returns focus to the ⌘K trigger instead of dropping it to the
  // top of the document.
  const restoreFocus = useRef<HTMLElement | null>(null);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        e.preventDefault();
        setOpen((v) => !v);
      }
      if (e.key === "Escape") setOpen(false);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  useEffect(() => {
    if (open) {
      restoreFocus.current = (document.activeElement as HTMLElement) ?? null;
      setQ("");
      setResults([]);
      setActive(0);
      setTimeout(() => inputRef.current?.focus(), 30);
    } else {
      restoreFocus.current?.focus?.();
      restoreFocus.current = null;
    }
  }, [open]);

  const navMatches: Result[] = q.length > 0
    ? nav
        .filter((n) => n.label.toLowerCase().includes(q.toLowerCase()))
        .slice(0, 5)
        .map((n) => ({ type: "page", label: n.label, sub: n.section, href: n.href }))
    : nav.slice(0, 7).map((n) => ({ type: "page", label: n.label, sub: n.section, href: n.href }));

  useEffect(() => {
    if (debounce.current) clearTimeout(debounce.current);
    if (q.length < 2) {
      setResults([]);
      return;
    }
    debounce.current = setTimeout(async () => {
      try {
        const res = await fetch(`/api/search?q=${encodeURIComponent(q)}`);
        const json = await res.json();
        setResults(json.results ?? []);
      } catch {
        setResults([]);
      }
    }, 180);
  }, [q]);

  const all = [...navMatches, ...results];

  const go = useCallback(
    (href: string) => {
      setOpen(false);
      router.push(href);
    },
    [router]
  );

  if (!open) return null;

  return (
    <div
      className="fixed inset-0 z-50 flex items-start justify-center bg-black/60 p-4 pt-[12vh] backdrop-blur-sm"
      onClick={() => setOpen(false)}
    >
      <div
        role="dialog"
        aria-modal="true"
        aria-label="Command palette"
        className="glass w-full max-w-xl overflow-hidden shadow-2xl animate-fade-up"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center gap-3 border-b border-white/[0.08] px-4 py-3">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#64748b" strokeWidth="2">
            <circle cx="11" cy="11" r="7" />
            <path d="M21 21l-4-4" />
          </svg>
          <input
            ref={inputRef}
            aria-label="Search servers, hosting, websites, email, domains, tickets and pages"
            className="w-full bg-transparent text-sm outline-none placeholder:text-slate-500"
            placeholder="Search servers, hosting, email, domains, tickets…"
            value={q}
            onChange={(e) => {
              setQ(e.target.value);
              setActive(0);
            }}
            onKeyDown={(e) => {
              if (e.key === "ArrowDown") {
                e.preventDefault();
                setActive((a) => Math.min(a + 1, all.length - 1));
              }
              if (e.key === "ArrowUp") {
                e.preventDefault();
                setActive((a) => Math.max(a - 1, 0));
              }
              if (e.key === "Enter" && all[active]) go(all[active].href);
            }}
          />
          <span className="kbd">esc</span>
        </div>
        <div className="max-h-[50vh] overflow-y-auto p-2">
          {all.length === 0 ? (
            <p className="px-3 py-6 text-center text-sm text-slate-500">No results.</p>
          ) : (
            all.map((r, i) => {
              // Emit a group header whenever the type changes. The flat order
              // matches the visual group order, so this reads as clean sections
              // while keyboard nav still walks a single top-to-bottom list.
              const showHeader = i === 0 || all[i - 1].type !== r.type;
              return (
                <div key={`${r.type}-${r.href}-${i}`}>
                  {showHeader && (
                    <p className="px-3 pb-1 pt-2 text-[10px] font-semibold uppercase tracking-wider text-slate-500">
                      {typeLabels[r.type] ?? r.type}
                    </p>
                  )}
                  <button
                    className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm transition-colors ${
                      i === active ? "bg-brand-500/20 text-white" : "text-slate-300 hover:bg-white/[0.05]"
                    }`}
                    onMouseEnter={() => setActive(i)}
                    onClick={() => go(r.href)}
                  >
                    <span className="w-5 text-center text-xs opacity-70">{typeIcons[r.type] ?? "→"}</span>
                    <span className="flex-1 truncate">{r.label}</span>
                    {r.sub && <span className="truncate text-xs text-slate-500">{r.sub}</span>}
                  </button>
                </div>
              );
            })
          )}
        </div>
      </div>
    </div>
  );
}

import { NextRequest, NextResponse } from "next/server";

function hostList(envVar: string | undefined): string[] {
  return (envVar ?? "")
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
}

/**
 * Reachable on every host regardless of portal mode: Next internals, the API
 * surface every portal's own client code calls (chat SSE, uploads, etc.),
 * and the auth utility pages every login form links to. Everything else is
 * scoped to exactly one portal below.
 */
function isUniversallyAllowed(pathname: string): boolean {
  return (
    pathname.startsWith("/_next") ||
    pathname.startsWith("/api/") ||
    pathname === "/favicon.ico" ||
    pathname.startsWith("/.well-known/") ||
    pathname === "/forgot-password" ||
    pathname === "/reset-password" ||
    // Both portal layouts redirect a staff/admin account without 2FA here to
    // enroll (enforce_staff_2fa) — account security settings aren't
    // customer-specific, and blocking this would stand between a legitimate
    // staff member and the one page that lets them satisfy the requirement.
    pathname === "/dashboard/settings"
  );
}

/**
 * Confines the admin/staff hostnames to exactly their own portal.
 *
 * app/admin/layout.tsx and app/staff/layout.tsx already refuse the WRONG
 * direction — /admin and /staff 404 on any host that isn't their own
 * NXEON_ADMIN_HOSTS/NXEON_STAFF_HOSTS. But nothing stopped the REVERSE: the
 * admin/staff hostnames proxy to the exact same Next.js backend as the main
 * site, so /dashboard, /login, /register, and every marketing page were
 * equally reachable there too — confirmed live 2026-09-02, a customer's full
 * dashboard (wallet, deploy, domains) loading on the staff-only subdomain.
 * Not a data leak (they only ever saw their own account), but it defeats the
 * point of a separate, minimal, operations-only surface, and reduces
 * whatever "hard to guess" value the admin subdomain has by leaving it fully
 * browsable/indexable as a second copy of the public site.
 *
 * Together with the two layouts' existing checks this makes the mapping
 * exact: admin host <-> /admin only, staff host <-> /staff only, every other
 * host <-> everything except /admin and /staff.
 */
export function middleware(req: NextRequest) {
  const host = (req.headers.get("host") ?? "").toLowerCase().split(":")[0];
  const { pathname } = req.nextUrl;

  const adminHosts = hostList(process.env.NXEON_ADMIN_HOSTS);
  const staffHosts = hostList(process.env.NXEON_STAFF_HOSTS);
  const isAdminHost = adminHosts.length > 0 && adminHosts.includes(host);
  const isStaffHost = staffHosts.length > 0 && staffHosts.includes(host);

  if (isAdminHost || isStaffHost) {
    const ownPrefix = isAdminHost ? "/admin" : "/staff";
    const ownLogin = isAdminHost ? "/admin/login" : "/staff/login";

    if (!isUniversallyAllowed(pathname) && !pathname.startsWith(ownPrefix)) {
      // The shared /login page (and any stray redirect to it — logout()
      // always sends there, regardless of who's logging out) lands on this
      // host's own dedicated login instead of 404ing a signed-out visitor.
      if (pathname === "/login") {
        const url = req.nextUrl.clone();
        url.pathname = ownLogin;
        return NextResponse.redirect(url);
      }
      // The bare root — where someone typing/bookmarking just the hostname
      // lands — goes to the portal itself rather than 404ing. The admin
      // vhost happens to have its own nginx-level `location = / return 302
      // /admin` that already covered this there (confirmed live), but the
      // staff vhost has no equivalent, so its root 404'd under this same
      // isolation logic. Handling it here covers both hosts the same way
      // regardless of nginx config: an authenticated visit shows the portal,
      // an unauthenticated one gets bounced on to ownLogin by the layout's
      // own existing redirect — no new auth logic needed either way.
      if (pathname === "/") {
        const url = req.nextUrl.clone();
        url.pathname = ownPrefix;
        return NextResponse.redirect(url);
      }
      return new NextResponse("Not found.", { status: 404 });
    }
  }

  // Server Components have no built-in way to read the current pathname —
  // app/admin/layout.tsx and app/staff/layout.tsx need it to special-case
  // their own /login sub-route (public, no Shell, no auth redirect) without
  // a redirect loop. Set on the REQUEST (not the response) so headers() in a
  // downstream Server Component actually sees it.
  const requestHeaders = new Headers(req.headers);
  requestHeaders.set("x-pathname", pathname);
  return NextResponse.next({ request: { headers: requestHeaders } });
}

