  resize: "Upgrade",
};

export function ServerTabs({
  initialTab,
  overview,
  manage,
  mods,
  controlPanel,
  metrics,
  console: consolePanel,
  files,
  snapshots,
  backups,
  networking,
  resize,
  activity,
