          const k = t.toLowerCase();
          const active = tab === k;
          return (
            <button
              key={k}
              type="button"
              onClick={() => {
                setTab(k);
                window.history.replaceState(null, "", `?tab=${k}`);
              }}
              className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
                active
                  ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white shadow-[0_4px_16px_-6px_rgb(111_71_245_/_0.6)]"
                  : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
              }`}
            >
              {TAB_LABELS[k] ?? t}
            </button>
          );
        })}
      </div>
      <div className="animate-fade-up">{panels[tab]}</div>
    </div>
  );

