import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

/**
 * Global portal search, powering the ⌘K palette / top-bar "Search anything".
 *
 * Searches across everything a caller can reach — servers, hosting plans,
 * hosting accounts, websites, mailboxes (email), domains and tickets — plus, for
 * admins, customers. Every result carries a `type` (for grouping + an icon) and a
 * ready-to-navigate `href` that jumps straight to the item.
 *
 * SCOPING is the security boundary and is applied per model:
 *   • Customers see ONLY their own rows (`userId` / relation scoped).
 *   • Admins see ACROSS accounts, and their result links point at the /admin
 *     equivalents.
 * Catalog rows (hosting plans) are the one non-owned type: everyone may see the
 * active plans; admins additionally see inactive ones.
 *
 * The response is `private, no-store` because for an admin it contains other
 * customers' hostnames, emails and ticket subjects — a shared cache keyed on the
 * `?q=` URL would otherwise replay one caller's results to the next.
 */
export async function GET(req: NextRequest) {
  const user = await currentUser();
  if (!user) {
    return NextResponse.json({ results: [] }, { status: 401, headers: NO_STORE_HEADERS });
  }
  const q = (req.nextUrl.searchParams.get("q") ?? "").trim();
  if (q.length < 2) return NextResponse.json({ results: [] }, { headers: NO_STORE_HEADERS });

  const isAdmin = user.role === "ADMIN";
  // Ownership filter reused across every customer-owned model.
  const own = isAdmin ? {} : { userId: user.id };
  const like = { contains: q, mode: "insensitive" as const };

  const results: { type: string; label: string; sub?: string; href: string }[] = [];

  // Everything runs concurrently; each block fails soft so one bad table can't
  // blank the whole palette.
  const soft = <T,>(p: Promise<T>, fallback: T): Promise<T> => p.catch(() => fallback);

  const [servers, plans, accounts, websites, mailboxes, domains, tickets, customers] =
    await Promise.all([
      // Servers (VPS + game). Match the hostname, the customer nickname, or the name.
      soft(
        db.server.findMany({
          where: { OR: [{ hostname: like }, { label: like }, { name: like }], ...own },
          include: { user: true },
          take: 6,
        }),
        [] as Array<{
          id: string;
          hostname: string;
          label: string | null;
          status: string;
          user: { email: string };
        }>,
      ),
      // Hosting plans (catalog — not owned). Customers see active plans only.
      soft(
        db.hostingPlan.findMany({
          where: {
            OR: [{ name: like }, { slug: like }, { tagline: like }],
            ...(isAdmin ? {} : { active: true }),
          },
          take: 4,
        }),
        [] as Array<{ id: string; name: string; slug: string; priceCents: number; active: boolean }>,
      ),
      // Hosting accounts. Match the primary domain or the jailed username.
      soft(
        db.hostingAccount.findMany({
          where: { OR: [{ primaryDomain: like }, { username: like }], ...own },
          include: { user: true },
          take: 5,
        }),
        [] as Array<{ id: string; primaryDomain: string; status: string; user: { email: string } }>,
      ),
      // Websites (VPS vhosts). Managed from their server's control panel, so the
      // result jumps to the owning server.
      soft(
        db.website.findMany({ where: { domain: like, ...own }, take: 5 }),
        [] as Array<{ id: string; domain: string; status: string; serverId: string }>,
      ),
      // Mailboxes (business email). Scoped through the subscription's owner.
      soft(
        db.mailbox.findMany({
          where: { address: like, ...(isAdmin ? {} : { subscription: { userId: user.id } }) },
          include: { subscription: { include: { user: true } } },
          take: 5,
        }),
        [] as Array<{ id: string; address: string; status: string; subscription: { user: { email: string } } }>,
      ),
      soft(
        db.domain.findMany({ where: { name: like, ...own }, take: 4 }),
        [] as Array<{ id: string; name: string; status: string }>,
      ),
      soft(
        db.ticket.findMany({ where: { subject: like, ...own }, take: 4 }),
        [] as Array<{ id: string; subject: string; status: string }>,
      ),
      // Customers — admin only.
      isAdmin
        ? soft(
            db.user.findMany({ where: { OR: [{ email: like }, { name: like }] }, take: 5 }),
            [] as Array<{ id: string; name: string; email: string }>,
          )
        : Promise.resolve([] as Array<{ id: string; name: string; email: string }>),
    ]);

  for (const s of servers) {
    results.push({
      type: "server",
      label: s.label || s.hostname,
      sub: isAdmin ? `${s.user.email} · ${s.status.toLowerCase()}` : s.status.toLowerCase(),
      href: isAdmin ? `/admin/servers/${s.id}` : `/dashboard/servers/${s.id}`,
    });
  }

  }

  for (const p of plans) {
    results.push({
      type: "hosting",
      label: p.name,
      sub: `hosting plan · $${(p.priceCents / 100).toFixed(2)}/mo${!p.active ? " · inactive" : ""}`,
      href: isAdmin ? "/admin/hosting" : "/dashboard/hosting",
    });
  }

  for (const a of accounts) {
    results.push({
      type: "hosting",
      label: a.primaryDomain,
      sub: isAdmin ? `${a.user.email} · ${a.status.toLowerCase()}` : `hosting · ${a.status.toLowerCase()}`,
      href: isAdmin ? "/admin/hosting" : `/dashboard/hosting/${a.id}`,
    });
  }

  for (const w of websites) {
    results.push({
      type: "website",
      label: w.domain,
      sub: `website · ${w.status.toLowerCase()}`,
      href: isAdmin ? `/admin/servers/${w.serverId}` : `/dashboard/servers/${w.serverId}`,
    });
  }

  for (const m of mailboxes) {
    results.push({
      type: "email",
      label: m.address,
      sub: isAdmin ? `${m.subscription.user.email} · ${m.status.toLowerCase()}` : `mailbox · ${m.status.toLowerCase()}`,
      href: isAdmin ? "/admin/mailboxes" : "/dashboard/email",
    });
  }

  for (const d of domains) {
    results.push({
      type: "domain",
      label: d.name,
      sub: d.status.toLowerCase(),
      href: isAdmin ? "/admin/domains" : `/dashboard/domains/${d.id}`,
    });
  }

  for (const t of tickets) {
    results.push({
      type: "ticket",
      label: t.subject,
      sub: t.status.toLowerCase(),
      href: isAdmin ? `/admin/support/${t.id}` : `/dashboard/support/${t.id}`,
    });
  }

  for (const u of customers) {
    results.push({ type: "customer", label: u.name, sub: u.email, href: `/admin/users/${u.id}` });
  }

  return NextResponse.json({ results: results.slice(0, 30) }, { headers: NO_STORE_HEADERS });
}

